-- Athena saved query (Product_B2C_Intl)
-- ID: 022c8af1-dbb6-4d20-b33d-069738d9004d
-- Name: Cohort Deals Organic click share of boosted listings - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp AS ( SELECT s.mri_session_id, s.route_id, CAST(s.doj AS VARCHAR) AS doj, CASE WHEN s.channel_exp_info IS NULL THEN 'null' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) > 2 THEN '3. DBD 2+' ELSE 'Others' END AS search_day, MAX(CASE WHEN s.cohort_type = 'BOOSTUI' THEN 1 ELSE 0 END) AS has_boostui_on_route FROM "user_interaction"."search_route_details" s WHERE s.__time >= TIMESTAMP '2026-04-24 18:30:00' AND s.__time < TIMESTAMP '2026-04-29 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.os = 'iOS' AND s.tp_channel = 'INVALID' AND s.country = 'IND' GROUP BY 1, 2, 3, 4, 5 ), -- Sessions that saw at least one BOOSTUI on a Same-Day search universe_sessions AS ( SELECT DISTINCT srp.mri_session_id FROM srp WHERE srp.search_day = '0. Same Day' AND srp.has_boostui_on_route = 1 ), -- One exp_variant per session (Same-Day rows only; change to all srp if you prefer) session_exp AS ( SELECT srp.mri_session_id, MAX(srp.exp_variant) AS exp_variant FROM srp JOIN universe_sessions u ON u.mri_session_id = srp.mri_session_id WHERE srp.search_day = '0. Same Day' GROUP BY 1 ), -- Boosted route tuples (Same-Day): cohort = BOOSTUI on SRP for that session/route/doj boosted_route_tuples AS ( SELECT DISTINCT srp.mri_session_id, srp.route_id, srp.doj FROM srp JOIN universe_sessions u ON u.mri_session_id = srp.mri_session_id WHERE srp.search_day = '0. Same Day' AND srp.has_boostui_on_route = 1 ), -- Raw SL lands (instances); join to Same-Day SRP so SL aligns to Same-Day route context sl_same_day AS ( SELECT sld.mri_session_id, sld.route_id, CAST(sld.doj AS VARCHAR) AS doj, sld.user_origin FROM "user_interaction"."seat_layout_details" sld INNER JOIN srp ON srp.mri_session_id = sld.mri_session_id AND srp.route_id = sld.route_id AND srp.doj = CAST(sld.doj AS VARCHAR) JOIN universe_sessions u ON u.mri_session_id = sld.mri_session_id WHERE sld.__time >= TIMESTAMP '2026-04-24 18:30:00' AND sld.__time < TIMESTAMP '2026-04-29 18:30:00' AND sld.country = 'IND' AND srp.search_day = '0. Same Day' ), sl_flagged AS ( SELECT sl.*, CASE WHEN br.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS is_boosted_route, CASE WHEN br.mri_session_id IS NOT NULL AND sl.user_origin LIKE 'BOOSTUI%' THEN 1 ELSE 0 END AS is_boosted_route_boosted_sl, CASE WHEN br.mri_session_id IS NOT NULL AND sl.user_origin IS NULL THEN 1 ELSE 0 END AS is_boosted_route_normal_sl FROM sl_same_day sl LEFT JOIN boosted_route_tuples br ON br.mri_session_id = sl.mri_session_id AND br.route_id = sl.route_id AND br.doj = sl.doj ) SELECT se.exp_variant, -- 1. Overall SL lands (all routes), Same-Day-aligned sessions in universe COUNT(*) AS overall_sl_land_instances, COUNT(DISTINCT sl.mri_session_id) AS overall_sl_land_sessions, -- 2. Boosted route + BOOSTUI% SL entry SUM(sl.is_boosted_route_boosted_sl) AS boosted_route_boosted_sl_instances, COUNT(DISTINCT CASE WHEN sl.is_boosted_route_boosted_sl = 1 THEN sl.mri_session_id END) AS boosted_route_boosted_sl_sessions, -- 3. Boosted route + user_origin IS NULL SUM(sl.is_boosted_route_normal_sl) AS boosted_route_normal_sl_instances, COUNT(DISTINCT CASE WHEN sl.is_boosted_route_normal_sl = 1 THEN sl.mri_session_id END) AS boosted_route_normal_sl_sessions FROM sl_flagged sl JOIN session_exp se ON se.mri_session_id = sl.mri_session_id GROUP BY 1 ORDER BY 1;
